document.addEventListener('DOMContentLoaded',()=>{const params=new URLSearchParams(location.search);const collection=(params.get('collection')||'').toLowerCase();const subCollections=['women','men','unisex','gift','gift-voucher'];if(!subCollections.includes(collection))return;const section=document.querySelector('.shop-section');if(!section)return;const back=document.createElement('a');back.className='collection-back-link';back.href=collection==='women'||collection==='men'||collection==='unisex'?'/shop/?collection=perfume#collection':'/shop/';back.innerHTML='← <span>Back to Collections</span>';back.setAttribute('aria-label','Back to collections');section.insertBefore(back,section.firstChild);const style=document.createElement('style');style.textContent='.collection-back-link{display:inline-flex;align-items:center;gap:10px;margin:0 0 28px;color:#1f1b17;text-decoration:none;font-size:14px;letter-spacing:.04em;transition:opacity .2s ease,transform .2s ease}.collection-back-link:hover{opacity:.65;transform:translateX(-3px)}@media(max-width:700px){.collection-back-link{margin-bottom:20px;font-size:13px}}';document.head.appendChild(style);});